  &DefaultButton;




function dir$dmsmail(p){
  this.constructor(p);
}
dir$dmsmail.prototype = new DirEvent();
dir$dmsmail.prototype.afterInit = function(){
  var p = this._dir;
}
dir$dmsmail.prototype.afterInit = function(renderType){
  var p = this._dir,g = p.grid();

	p.request('request_ma_smail', '', '' , function(pp, d, run){
		if (run) {
			p.setDisabled('ma_smail', true);
		}
	});

	p.jObject('vpassword').attr('type', 'password');

	if(p.options.action == 'NEW'){
		p.valForm('vpassword', '');
	}else{
		p.valForm('vpassword', '*******' + String.fromCharCode(255));
	}

  dir$dmsmailDisabledMasterField(p, g);

}
dir$dmsmail.prototype.beforeButtonDialogClick = function(ma_smail){
  var p = this._dir;
  switch (ma_smail) {
    case 'ok':
		p.valForm('mk_mail', p.valForm('vpassword'));
    default:
      break;
  }
  return true;
}


function dir$dmsmailDisabledMasterField(p, g){

  if(p.valForm('ma_smail').trim() != '')
  {
    p.setDisabled('ma_smail', true);
  }
  else
  {
    p.setDisabled('ma_smail', false);
  }
}







		.control-label.s_mail, .control-label.ten_mail
		{	
			//font-weight:bold;	
			color: #499b98;;
		}







						SELECT 
							CASE 
								WHEN MAX(ma_smail) IS NULL THEN 'SM001'
								ELSE 'SM' + RIGHT('00' + CAST(CAST(SUBSTRING(MAX(ma_smail), 3, LEN(MAX(ma_smail))) AS INT) + 1 AS VARCHAR), 3)
							END AS [!ma_smail]
						FROM dmsmail






		SELECT ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) AS row_num, * INTO #temp_d FROM #data;

		DECLARE @i int, @ci int, @next_num int;
		SET @i = 1

		SELECT @ci = MAX(row_num) FROM #temp_d
		SELECT @next_num = ISNULL(CAST(SUBSTRING(MAX(ma_smail), 3, 10) AS INT) + 1, 1) FROM dmsmail;

		WHILE @i <= @ci
		BEGIN
		    DECLARE @current_s_mail varchar(255);
			SELECT @current_s_mail = s_mail FROM #temp_d WHERE row_num = @i;

			UPDATE #data 
			SET ma_smail = 'SM' + RIGHT('00' + CAST(@next_num AS VARCHAR(3)), 3)
			WHERE s_mail = @current_s_mail;

			SET @i = @i + 1
			SET @next_num = @next_num + 1;
		END

		UPDATE #data set unit_id = @@unit;

		@@insert
